private void btn_GiayChungNhan_Gop_Click(object sender, EventArgs e)
{
    try
    {
        SIM_Student obj = new SIM_Student();
        DataTable dtStudents = obj.GetDataTable("SIM_Student_SearchStudentMarkSummary_TN",
                                                  "@ClassID", uClassID_Search.ClassIDEditValue,
                                                  "@CourseID", uClassID_Search.CourseIDEditValue,
                                                  "@BranchID", uClassID_Search.BranchEditValue,
                                                  "@TrainingLevelID", uClassID_Search.TrainingLevelIDEditValue,
                                                  "@ScienceID", uClassID_Search.ScienceIDEditValue,
                                                  "@Status", uStudentStatus.EditValueInt32);

        if (dtStudents == null || dtStudents.Rows.Count == 0)
        {
            MessageBox.Show("Không có sinh viên nào để xuất!", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        string templatePath = System.Windows.Forms.Application.StartupPath + @"\Template\FileSinhVien\GCNTNTT.doc";
        if (!File.Exists(templatePath))
        {
            MessageBox.Show("Không tìm thấy file mẫu: " + templatePath);
            return;
        }

        string savePath = GetSaveFilePath("GCNTNTT_Gop.doc");
        if (string.IsNullOrEmpty(savePath))
        {
            return;
        }

        Aspose.Words.Document mergedDocument = null;
        foreach (DataRow row in dtStudents.Rows)
        {
            Aspose.Words.Document reportStudent = new Aspose.Words.Document(templatePath);
            FillGiayChungNhanMailMerge(reportStudent, row);

            if (mergedDocument == null)
            {
                mergedDocument = reportStudent;
            }
            else
            {
                mergedDocument.AppendDocument(reportStudent, ImportFormatMode.KeepSourceFormatting);
            }
        }

        if (mergedDocument != null)
        {
            SaveAndOpenFile(savePath, mergedDocument);
            MessageBox.Show("Xuất file gộp thành công!", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Information);
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Lỗi khi xuất: " + ex.Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error);
    }
}

