private void SaveAndOpenFile(string filePath, Aspose.Words.Document document)
{
    try
    {
        ApplySafePrintMargins(document);
        document.Save(filePath);

        if (File.Exists(filePath))
        {
            Console.WriteLine("Đã lưu file: " + filePath);
            // System.Diagnostics.Process.Start(filePath); // mở nếu muốn
        }
        else
        {
            MessageBox.Show("Không lưu được file: " + filePath);
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Lỗi khi lưu file: " + ex.Message);
    }
}

private void ApplySafePrintMargins(Aspose.Words.Document document)
{
    // Lề tối thiểu ~10mm để phù hợp hầu hết máy in, tránh Word cảnh báo margin quá nhỏ
    double minMargin = Aspose.Words.ConvertUtil.MillimeterToPoint(10);

    foreach (Aspose.Words.Section section in document.Sections)
    {
        Aspose.Words.PageSetup pageSetup = section.PageSetup;

        if (pageSetup.TopMargin < minMargin)
            pageSetup.TopMargin = minMargin;
        if (pageSetup.BottomMargin < minMargin)
            pageSetup.BottomMargin = minMargin;
        if (pageSetup.LeftMargin < minMargin)
            pageSetup.LeftMargin = minMargin;
        if (pageSetup.RightMargin < minMargin)
            pageSetup.RightMargin = minMargin;
    }
}

